const menu=document.querySelector('.menu'),nav=document.querySelector('nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',open);menu.setAttribute('aria-label',open?'Cerrar menú':'Abrir menú');menu.textContent=open?'×':'☰'});nav.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.setAttribute('aria-label','Abrir menú');menu.textContent='☰'}));
let piece='knight',position=[4,3];const pieces={knight:{symbol:'♞',name:'Caballo',tip:'El caballo se mueve en «L» y puede saltar sobre otras piezas.'},bishop:{symbol:'♝',name:'Alfil',tip:'El alfil recorre las diagonales y siempre permanece en casillas del mismo color.'},rook:{symbol:'♜',name:'Torre',tip:'La torre se mueve en línea recta, por filas o columnas.'}};const board=document.querySelector('.board');function legal(r,c){const dr=Math.abs(r-position[0]),dc=Math.abs(c-position[1]);if(!dr&&!dc)return false;return piece==='knight'?(dr===2&&dc===1)||(dr===1&&dc===2):piece==='bishop'?dr===dc:dr===0||dc===0}function render(){board.replaceChildren();for(let r=0;r<8;r++)for(let c=0;c<8;c++){const selected=r===position[0]&&c===position[1],available=legal(r,c),b=document.createElement('button');b.type='button';b.className='square'+((r+c)%2?' dark':'')+(selected?' selected':'')+(available?' available':'');b.setAttribute('aria-label',String.fromCharCode(97+c)+(8-r)+(selected?', '+pieces[piece].name:available?', movimiento disponible':', movimiento no disponible'));b.setAttribute('aria-disabled',String(!available&&!selected));b.textContent=selected?pieces[piece].symbol:'';b.addEventListener('click',()=>{if(legal(r,c)){position=[r,c];render();document.getElementById('piece-tip').textContent='¡Bien! '+pieces[piece].name+' a '+String.fromCharCode(97+c)+(8-r)+'. '+pieces[piece].tip;board.children[r*8+c].focus()}});board.append(b)}}render();document.querySelectorAll('[data-piece]').forEach(b=>b.addEventListener('click',()=>{piece=b.dataset.piece;position=[4,3];document.querySelectorAll('[data-piece]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.getElementById('piece-tip').textContent=pieces[piece].tip;render()}));document.getElementById('reset').addEventListener('click',()=>{position=[4,3];document.getElementById('piece-tip').textContent=pieces[piece].tip;render()});const form=document.getElementById('inquiry');form.addEventListener('submit',()=>{document.getElementById('inquiry-text').value='¡Hola, Bravo’s! Quisiera información sobre las clases virtuales de ajedrez.\n\nMi experiencia: '+document.getElementById('experience').value+'.\n\n¿Podrían indicarme el temario, las edades admitidas, los grupos, los horarios, las tarifas vigentes y cómo inscribirme? ¡Gracias!';});document.getElementById('year').textContent=new Date().getFullYear();

const galleryPhotos=[{"id": 1, "category": "clases", "label": "Clases y actividades", "title": "Aprender entre amigos", "caption": "Una jornada de práctica y aprendizaje frente al tablero.", "alt": "Niños practicando ajedrez en el aula del Club Bravo’s"}, {"id": 4, "category": "equipo", "label": "Equipo y torneos", "title": "Bravo’s en el Interclubes", "caption": "Torneo Nacional de Ajedrez Interclubes 2023 · Cochabamba.", "alt": "Integrantes de Bravo’s junto al estandarte del Torneo Nacional Interclubes 2023"}, {"id": 8, "category": "clases", "label": "Clases y actividades", "title": "El tablero nos reúne", "caption": "Compartir el juego y descubrir nuevas posibilidades.", "alt": "Instructor acompañando a niños que juegan ajedrez al aire libre"}, {"id": 5, "category": "logros", "label": "Reconocimientos", "title": "Celebrar el esfuerzo", "caption": "Medallas, diplomas y la alegría de seguir aprendiendo.", "alt": "Alumnos de Bravo’s mostrando sus medallas y diplomas junto a sus acompañantes"}, {"id": 6, "category": "logros", "label": "Reconocimientos", "title": "Experiencias que motivan", "caption": "Una fotografía de equipo para recordar el camino compartido.", "alt": "Equipo de Bravo’s con medallas junto a una exhibición de trofeos"}, {"id": 7, "category": "equipo", "label": "Equipo y torneos", "title": "Un mismo equipo", "caption": "Encuentros y recuerdos alrededor de una misma pasión.", "alt": "Integrantes del club reunidos junto al estandarte de Bravo’s"}, {"id": 3, "category": "equipo", "label": "Equipo y torneos", "title": "Juntos, dentro y fuera del tablero", "caption": "Un recuerdo del equipo en Cochabamba.", "alt": "Grupo de alumnos de Bravo’s frente al Cristo de la Concordia", "fit": "contain"}, {"id": 2, "category": "logros", "label": "Reconocimientos", "title": "Un reconocimiento a nuestra labor", "caption": "Reconocimiento a la academia por su aporte al ajedrez de Cochabamba.", "alt": "Placa de reconocimiento a la academia de ajedrez Bravos por su aporte al ajedrez de Cochabamba", "fit": "contain"}, {"id": 9, "category": "clases", "label": "Clases y actividades", "title": "Ajedrez y creatividad", "caption": "El juego también se vive con imaginación y entusiasmo.", "alt": "Niños participando en una actividad con disfraces de piezas de ajedrez"}];
const galleryCards=[...document.querySelectorAll('.gallery-card')];
let galleryFilter='all',activePhoto=0,lastPhotoTrigger=null;
const viewer=document.getElementById('photo-viewer');
function visiblePhotos(){return galleryPhotos.map((p,i)=>({p,i})).filter(({p})=>galleryFilter==='all'||p.category===galleryFilter).map(({i})=>i)}
function showPhoto(index){activePhoto=index;const p=galleryPhotos[index],visible=visiblePhotos();document.getElementById('photo-large').src='assets/bravos-'+p.id+'.webp';document.getElementById('photo-large').alt=p.alt;document.getElementById('photo-title').textContent=p.title;document.getElementById('photo-description').textContent=p.caption;document.getElementById('photo-category').textContent=p.label;document.getElementById('photo-position').textContent=(visible.indexOf(index)+1)+' / '+visible.length;document.getElementById('photo-prev').disabled=visible.length<2;document.getElementById('photo-next').disabled=visible.length<2}
function stepPhoto(direction){const visible=visiblePhotos();showPhoto(visible[(visible.indexOf(activePhoto)+direction+visible.length)%visible.length])}
document.querySelectorAll('[data-filter]').forEach(button=>button.addEventListener('click',()=>{galleryFilter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button))});galleryCards.forEach(c=>{c.hidden=galleryFilter!=='all'&&c.dataset.category!==galleryFilter});document.querySelector('.gallery-grid').classList.toggle('is-filtered',galleryFilter!=='all');document.getElementById('gallery-count').textContent=visiblePhotos().length+' momentos'}));
galleryCards.forEach(button=>button.addEventListener('click',()=>{lastPhotoTrigger=button;showPhoto(Number(button.dataset.photo));viewer.showModal();document.body.style.overflow='hidden'}));
document.getElementById('photo-close').addEventListener('click',()=>viewer.close());document.getElementById('photo-prev').addEventListener('click',()=>stepPhoto(-1));document.getElementById('photo-next').addEventListener('click',()=>stepPhoto(1));
viewer.addEventListener('click',e=>{if(e.target===viewer){const r=viewer.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)viewer.close()}});
viewer.addEventListener('keydown',e=>{if(e.key==='ArrowRight'){e.preventDefault();stepPhoto(1)}if(e.key==='ArrowLeft'){e.preventDefault();stepPhoto(-1)}});viewer.addEventListener('close',()=>{document.body.style.overflow='';if(lastPhotoTrigger)lastPhotoTrigger.focus()});

const clubContent=window.BRAVOS_CONTENT||{};
const htmlText=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function safeContentUrl(value){if(!value)return '';try{const u=new URL(value,location.href);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}}
function moduleLink(title){return 'https://wa.me/59172560021?text='+encodeURIComponent('¡Hola, Bravo’s! Me interesa el '+title+'. Quisiera conocer los horarios, las tarifas y cómo inscribirme a las clases virtuales.')}
function modulePosterMarkup(module){const tone=['gold','navy','copper'].includes(module.tone)?module.tone:'copper',piece=['king','knight','rook'].includes(module.piece)?module.piece:'knight';const topics=module.topics.map((t,i)=>'<li><span>'+String(i+1).padStart(2,'0')+'</span><div><h4>'+htmlText(t.title)+'</h4>'+(t.description?'<p>'+htmlText(t.description)+'</p>':'')+'</div></li>').join('');return '<article class="module-poster tone-'+tone+'" id="module-'+module.id+'" role="tabpanel" aria-labelledby="module-tab-'+module.id+'" tabindex="0"><div class="poster-topline"><span>TEMARIO · CLASES VIRTUALES</span><span>BRAVO’S</span></div><div class="poster-layout"><div class="poster-content"><h3>'+htmlText(module.title)+'</h3><span class="poster-divider"></span><ol class="poster-topics">'+topics+'</ol></div><aside class="poster-art" aria-hidden="true"><img class="poster-photo" src="'+htmlText(safeContentUrl(module.photo||'assets/bravos-logo.webp'))+'" alt="" width="160" height="160" loading="lazy"><svg class="poster-piece" viewBox="0 0 180 240"><use href="#bravos-'+piece+'"/></svg><img class="poster-seal" src="assets/bravos-logo.webp" alt="" width="94" height="94" loading="lazy"></aside></div><div class="poster-bottom"><p>'+htmlText(module.footer||'Clases virtuales de ajedrez')+'</p><a class="button" href="'+htmlText(moduleLink(module.title))+'" target="_blank" rel="noopener">Consultar por WhatsApp <span>↗</span></a></div></article>'}
const moduleNavigation=document.querySelector('.module-nav'),modulePanels=document.querySelector('.module-posters');
if(Array.isArray(clubContent.modules)&&clubContent.modules.length){const modules=clubContent.modules.map(m=>({...m}));if(clubContent.extraModule&&Array.isArray(clubContent.extraModule.topics)&&clubContent.extraModule.topics.length){const before=modules.findIndex(m=>m.id===clubContent.extraModuleBefore);modules.splice(before<0?modules.length:before,0,{...clubContent.extraModule})}const usedIds=new Set();modules.forEach((m,i)=>{const base=String(m.id||'extra-'+i).replace(/[^a-z0-9-]/gi,'-').toLowerCase();m.id=usedIds.has(base)?base+'-'+i:base;usedIds.add(m.id);m.topics=Array.isArray(m.topics)?m.topics:[]});moduleNavigation.innerHTML=modules.map((m,i)=>'<button type="button" id="module-tab-'+m.id+'" role="tab" aria-controls="module-'+m.id+'" aria-selected="'+(i===0)+'" tabindex="'+(i===0?'0':'-1')+'">'+htmlText(m.title)+'</button>').join('');modulePanels.innerHTML=modules.map(modulePosterMarkup).join('')}
const moduleTabs=[...moduleNavigation.querySelectorAll('[role="tab"]')];
function activateModule(tab){moduleTabs.forEach(t=>{const selected=t===tab;t.setAttribute('aria-selected',String(selected));t.tabIndex=selected?0:-1;const panel=document.getElementById(t.getAttribute('aria-controls'));if(panel)panel.hidden=!selected})}
moduleTabs.forEach((tab,i)=>{tab.addEventListener('click',()=>activateModule(tab));tab.addEventListener('keydown',e=>{let next=i;if(e.key==='ArrowRight')next=(i+1)%moduleTabs.length;else if(e.key==='ArrowLeft')next=(i-1+moduleTabs.length)%moduleTabs.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=moduleTabs.length-1;else return;e.preventDefault();activateModule(moduleTabs[next]);moduleTabs[next].focus()})});if(moduleTabs.length)activateModule(moduleTabs[0]);

// Future media: fill content.js when the club provides the files.
const classVideo=clubContent.classVideo||{};
if(safeContentUrl(classVideo.src)){const container=document.getElementById('class-video'),fallback=container.cloneNode(true),video=document.createElement('video');video.controls=true;video.playsInline=true;video.preload='metadata';video.poster=classVideo.poster||'assets/bravos-1.webp';video.src=safeContentUrl(classVideo.src);video.setAttribute('aria-label','Una clase virtual de ajedrez en el Club Bravo’s');if(safeContentUrl(classVideo.captions)){const track=document.createElement('track');track.kind='captions';track.srclang='es';track.label='Español';track.src=safeContentUrl(classVideo.captions);video.append(track)}container.replaceChildren(video);const description=document.getElementById('video-description');description.textContent='Conoce una clase virtual en Bravo’s: una mirada cercana a cómo se juega y se aprende, una partida a la vez.';video.addEventListener('error',()=>{container.replaceChildren(...fallback.childNodes);description.textContent='El video no está disponible en este momento. Consulta con el club para conocer nuestras clases virtuales.'},{once:true})}
const announcement=clubContent.novemberAnnouncement||{};
if(safeContentUrl(announcement.image)){const art=document.getElementById('november-art'),original=art.firstElementChild.cloneNode(true),image=document.createElement('img'),link=document.createElement('a'),description=document.getElementById('announcement-description'),originalDescription=description.textContent;image.src=safeContentUrl(announcement.image);image.alt=announcement.alt||'Anuncio de noviembre de Bravo’s';image.className='announcement-image';image.loading='lazy';link.href=image.src;link.className='announcement-image-link';link.target='_blank';link.rel='noopener';link.setAttribute('aria-label','Ver completo el anuncio de noviembre');link.append(image);art.replaceChildren(link);if(announcement.title)document.getElementById('announcement-title').textContent=announcement.title;description.textContent=announcement.description||'Conoce nuestro anuncio de noviembre y consulta los detalles por WhatsApp.';if(announcement.label)document.getElementById('announcement-label').textContent=announcement.label;image.addEventListener('error',()=>{art.replaceChildren(original);description.textContent=originalDescription},{once:true})}
const socials=clubContent.socials||{};
for(const network of ['facebook','tiktok']){const link=document.querySelector('[data-social="'+network+'"]'),url=safeContentUrl(socials[network]);if(link&&url){link.href=url;link.hidden=false;if(network==='tiktok')document.getElementById('tiktok-pending').hidden=true}}

const motionButton=document.getElementById('motion-toggle'),reduceMedia=window.matchMedia('(prefers-reduced-motion: reduce)');
function refreshMotionButton(){const reduced=document.documentElement.dataset.motion==='reduced';motionButton.setAttribute('aria-pressed',String(reduced));motionButton.textContent=reduced?'Activar animaciones':'Reducir movimiento'}
if(reduceMedia.matches)motionButton.hidden=true;refreshMotionButton();
motionButton.addEventListener('click',()=>{const reduced=document.documentElement.dataset.motion!=='reduced';if(reduced)document.documentElement.dataset.motion='reduced';else delete document.documentElement.dataset.motion;try{localStorage.setItem('bravos-reduce-motion',reduced?'1':'0')}catch{}refreshMotionButton()});
if('IntersectionObserver' in window&&!reduceMedia.matches&&document.documentElement.dataset.motion!=='reduced'){const revealSections=[...document.querySelectorAll('.school,.learning,.quiz-section,.formation,.poster-syllabus,.gallery-section,.video-section,.faq,.social-section')];revealSections.forEach(section=>section.setAttribute('data-reveal',''));document.documentElement.classList.add('reveal-ready');const sectionObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('is-visible');sectionObserver.unobserve(entry.target)}})},{threshold:.06,rootMargin:'0px 0px -15px 0px'});revealSections.forEach(section=>sectionObserver.observe(section))}

