if(quizAppUrl){quizAppLink.href=quizAppUrl;quizAppLink.hidden=false}
const quizVideo=clubContent.quizVideo||{};
if(safeContentUrl(quizVideo.src)){const container=document.getElementById('quiz-video'),original=container.firstElementChild.cloneNode(true),note=document.getElementById('quiz-demo-note'),originalNote=note.textContent,video=document.createElement('video');video.controls=true;video.playsInline=true;video.preload='metadata';video.src=safeContentUrl(quizVideo.src);if(safeContentUrl(quizVideo.poster))video.poster=safeContentUrl(quizVideo.poster);video.setAttribute('aria-label','Demostración de Bravos Quiz: preguntas de ajedrez en tiempo real');if(safeContentUrl(quizVideo.captions)){const track=document.createElement('track');track.kind='captions';track.srclang='es';track.label='Español';track.src=safeContentUrl(quizVideo.captions);video.append(track)}container.replaceChildren(video);note.textContent='Conoce Bravos Quiz en acción: cómo entrar con un PIN, participar y seguir la clasificación.';video.addEventListener('error',()=>{container.replaceChildren(original);note.textContent=originalNote},{once:true})}
